class Solution {
    public int[] constructArray(int n, int k) {
        int[] ans = new int[n];
        int lo = 1, hi = k + 1;
        for (int i = 0; i <= k; i++) {
            ans[i] = (i % 2 == 0) ? lo++ : hi--;
        }
        for (int i = k + 1; i < n; i++) {
            ans[i] = i + 1;
        }
        return ans;
    }
}

class Solution {
    public int[] constructArray(int n, int k) {
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) ans[i] = i + 1;
        for (int i = 1; i < k; i++) {
            reverse(ans, i, n - 1);
        }
        return ans;
    }

    private void reverse(int[] arr, int l, int r) {
        while (l < r) {
            int tmp = arr[l];
            arr[l] = arr[r];
            arr[r] = tmp;
            l++;
            r--;
        }
    }
}
